# -*- coding: utf-8 -*-
from __future__ import annotations
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile
from datetime import datetime
from pathlib import Path

TITLE = "TÍCH HỢP BẢNG KHÓA QĐ3805 VÀO ENGINE SÁP NHẬP TOÀN CẤP"
EMBEDDED_FILES = {'app/services/school_merger_level_batch_service.py': '', 'app/templates/data_tools/school_merger_level_batch.html': ''}
REGISTRY_B64 = ''
EXCEL_B64 = ''
REGISTRY_REL = Path("data/school_merger_registry/qd3805_level_lock.json")
EXCEL_REL = Path("exports/Bang_khoa_cap_sap_nhap_QD3805/Bang_khoa_cap_sap_nhap_QD3805.xlsx")
EXPECTED = {"MN": (192, 51, 0, 1), "TH": (161, 67, 73, 1), "THCS": (116, 36, 88, 1)}


def db_fingerprint(db: Path) -> str:
    h = hashlib.sha256(); found = False
    for p in (db, Path(str(db) + "-wal")):
        if p.exists():
            found = True; h.update(p.name.encode("utf-8"))
            with p.open("rb") as f:
                for c in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(c)
    return h.hexdigest() if found else "MISSING"


def locate_root() -> Path:
    for c in (Path.cwd(), Path(r"C:\PhoCap"), Path(__file__).resolve().parent):
        if (c / "app" / "main.py").exists() and (c / "data" / "phocap.db").exists():
            return c.resolve()
    raise RuntimeError(r"Không tìm thấy dự án. Hãy chép bộ cài vào C:\PhoCap rồi chạy lại.")


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=path.name + ".", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data); f.flush(); os.fsync(f.fileno())
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            try: os.unlink(tmp)
            except Exception: pass


def main() -> None:
    root = locate_root(); db = root / "data" / "phocap.db"
    db_before = db_fingerprint(db)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup = root / "backups" / f"backup_truoc_tich_hop_qd3805_vao_sap_nhap_toan_cap_{stamp}"
    service = root / "app/services/school_merger_level_batch_service.py"
    template = root / "app/templates/data_tools/school_merger_level_batch.html"
    print("=" * 112); print(TITLE); print(f"Dự án: {root}"); print(f"Database: {db}")
    print("Nguyên tắc: KHÔNG thực hiện sáp nhập; KHÔNG chủ động ghi phocap.db."); print("=" * 112)

    if not service.exists() or not template.exists():
        raise RuntimeError("Thiếu chức năng Sáp nhập toàn cấp hiện tại. Hãy cài chức năng Sáp nhập toàn cấp trước.")
    service_src = service.read_text(encoding="utf-8", errors="replace")
    for marker in ("def build_level_batch_preview", "def execute_level_batch", "LEVEL_BATCH_CONFIRM_PHRASE"):
        if marker not in service_src:
            raise RuntimeError(f"Tệp dịch vụ toàn cấp không đúng nền chức năng: thiếu {marker}")

    backup.mkdir(parents=True, exist_ok=False)
    touched = [service, template, root / REGISTRY_REL, root / EXCEL_REL]
    for p in touched:
        if p.exists():
            bp = backup / p.relative_to(root); bp.parent.mkdir(parents=True, exist_ok=True); shutil.copy2(p, bp)

    try:
        # Cài lại đúng registry đi kèm bộ này để service và dữ liệu khóa luôn đồng bộ.
        atomic_write(root / REGISTRY_REL, base64.b64decode(REGISTRY_B64))
        atomic_write(root / EXCEL_REL, base64.b64decode(EXCEL_B64))
        for rel, b64 in EMBEDDED_FILES.items():
            atomic_write(root / rel, base64.b64decode(b64))

        py_compile.compile(str(service), doraise=True)
        try:
            from jinja2 import Environment
            Environment().parse(template.read_text(encoding="utf-8"))
        except ImportError:
            pass

        # Kiểm tra registry độc lập với DB.
        reg = json.loads((root / REGISTRY_REL).read_text(encoding="utf-8"))
        if reg.get("schema") != "QD3805_LEVEL_LOCK_2026" or reg.get("effective_school_year") != "2026-2027":
            raise RuntimeError("Registry QĐ3805 không đúng schema/năm hiệu lực đã khóa.")

        env = os.environ.copy(); env["PYTHONPATH"] = str(root); env["PYTHONIOENCODING"] = "utf-8"
        code = (
            "import json; from app.services.school_merger_level_batch_service import registry_level_summary; "
            "print(json.dumps({c:registry_level_summary(c) for c in ('MN','TH','THCS')}, ensure_ascii=True))"
        )
        cp = subprocess.run([sys.executable, "-c", code], cwd=str(root), env=env, capture_output=True, text=True, timeout=60)
        if cp.returncode != 0:
            raise RuntimeError("Smoke audit registry lỗi:\n" + (cp.stdout or "") + "\n" + (cp.stderr or ""))
        data = json.loads((cp.stdout or "").strip().splitlines()[-1])
        for level, (actions, keep, special, unresolved) in EXPECTED.items():
            got = data[level]
            if int(got["action_count"]) != actions or int(got["keep_count"]) != keep or int(got["special_count"]) != special or int(got["unresolved_count"]) != unresolved:
                raise RuntimeError(f"Số khóa {level} không đúng: {got}")

        if db_fingerprint(db) != db_before:
            raise RuntimeError("Database thay đổi trong lúc cài/smoke audit. Dừng và khôi phục mã nguồn.")

        print(); print("=" * 112)
        print("CÀI ĐẶT THÀNH CÔNG - ENGINE TOÀN CẤP ĐÃ KHÓA THEO QĐ3805")
        print("Database: KHÔNG THAY ĐỔI")
        print("MN: 192 phương án tác động + 51 giữ nguyên; 1 dòng chưa có phương án rõ.")
        print("TH: 161 phương án tác động + 67 giữ nguyên; 73 liên cấp/đặc thù tách riêng; 1 dòng chưa có phương án rõ.")
        print("THCS: 116 phương án tác động + 36 giữ nguyên; 88 liên cấp/đặc thù liên quan tách riêng; 1 dòng chưa có phương án rõ.")
        print("12 quan hệ THCS -> THPT: luôn thuộc LIÊN CẤP/ĐẶC THÙ, không chạy trong batch THCS thuần.")
        print("Nút SÁP NHẬP TOÀN CẤP chỉ có thể mở khi mọi operation QĐ3805 của batch thuần ghép đủ và CHẶN = 0.")
        print(f"Backup mã nguồn trước cài: {backup}")
        print("=" * 112)
    except Exception:
        for p in touched:
            bp = backup / p.relative_to(root)
            if bp.exists():
                p.parent.mkdir(parents=True, exist_ok=True); shutil.copy2(bp, p)
            elif p.exists() and p in (root / REGISTRY_REL, root / EXCEL_REL):
                try: p.unlink()
                except Exception: pass
        raise


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print(); print("=" * 112)
        print("DỪNG AN TOÀN - TÍCH HỢP QĐ3805 VÀO SÁP NHẬP TOÀN CẤP")
        print("Mã nguồn/registry đã được khôi phục nếu đã chạm file.")
        print("Lỗi:", exc)
        print("Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.")
        print("=" * 112)
        raise SystemExit(1)
